def _compute_display_name(self):
    super()._compute_display_name()
    for workcenter in self:
        # Show the red icon(workcenter is blocked) only when the Gantt view is accessed from MRP > Planning > Planning by Workcenter.
        if self.env.context.get('group_by') and self.env.context.get('show_workcenter_status') and workcenter.working_state == 'blocked':
            workcenter.display_name = f"{workcenter.display_name}\u00A0\u00A0🔴"

def _check_alternative_workcenter(self):
    for workcenter in self:
        if workcenter in workcenter.alternative_workcenter_ids:
            raise ValidationError(_("Workcenter %s cannot be an alternative of itself.", workcenter.name))

def _compute_kanban_dashboard_graph(self):
    week_range, date_start, date_stop = self._get_week_range_and_first_last_days()
    load_data = self._get_workcenter_load_per_week(week_range, date_start, date_stop)
    load_graph_data = self._prepare_graph_data(load_data, week_range)
    for wc in self:
        wc.kanban_dashboard_graph = json.dumps(load_graph_data[wc.id])

def _get_workcenter_load_per_week(self, week_range, date_start, date_stop):
    load_data = {rec: {} for rec in self}
    # demo data
    has_workorder = self.env['mrp.workorder'].search_count([('workcenter_id', 'in', self.ids)], limit=1)
    if not has_workorder:
        for wc in self:
            load_limit = 40     # default max load per week is 40 hours on a new workcenter
            load_data[wc] = {week_start: randint(0, int(load_limit * 2)) for week_start in week_range}
        return load_data

    result = self.env['mrp.workorder']._read_group(
        [('workcenter_id', 'in', self.ids), ('state', 'in', ('pending', 'waiting', 'ready', 'progress')),
         ('production_date', '>=', date_start), ('production_date', '<=', date_stop)],
        ['workcenter_id', 'production_date:week'], ['duration_expected:sum'])
    for r in result:
        load_in_hours = round(r[2] / 60, 1)
        load_data[r[0]].update({r[1]: load_in_hours})
    return load_data

def _prepare_graph_data(self, load_data, week_range):
    graph_data = {wid: [] for wid in self._ids}
    has_workorder = self.env['mrp.workorder'].search_count([('workcenter_id', 'in', self.ids)], limit=1)
    for workcenter in self:
        load_limit = workcenter.resource_calendar_id.hours_per_week
        wc_data = {'is_sample_data': not has_workorder, 'labels': list(week_range.values())}
        load_bar = []
        excess_bar = []
        for week_start in week_range:
            load_bar.append(min(load_data[workcenter].get(week_start, 0), load_limit))
            excess_bar.append(max(float_round(load_data[workcenter].get(week_start, 0) - load_limit, precision_digits=1, rounding_method='HALF-UP'), 0))
        wc_data['values'] = [load_bar, load_limit, excess_bar]
        graph_data[workcenter.id].append(wc_data)
    return graph_data

def _compute_working_state(self):
    # We search for a productivity line associated to this workcenter having no `date_end`.
    # If we do not find one, the workcenter is not currently being used. If we find one, according
    # to its `type_loss`, the workcenter is either being used or blocked.
    time_log_by_workcenter = {}
    for time_log in self.env['mrp.workcenter.productivity'].search([
        ('workcenter_id', 'in', self.ids),
        ('date_end', '=', False),
    ]):
        wc = time_log.workcenter_id
        if wc not in time_log_by_workcenter:
            time_log_by_workcenter[wc] = time_log

    for workcenter in self:
        time_log = time_log_by_workcenter.get(workcenter._origin)
        if not time_log:
            # the workcenter is not being used
            workcenter.working_state = 'normal'
        elif time_log.loss_type in ('productive', 'performance'):
            # the productivity line has a `loss_type` that means the workcenter is being used
            workcenter.working_state = 'done'
        else:
            # the workcenter is blocked
            workcenter.working_state = 'blocked'

def _compute_oee(self):
    time_data = self.env['mrp.workcenter.productivity']._read_group(
        domain=[
            ('date_start', '>=', fields.Datetime.to_string(datetime.now() - relativedelta.relativedelta(months=1))),
            ('workcenter_id', 'in', self.ids),
            ('date_end', '!=', False),
        ],
        groupby=['workcenter_id', 'loss_type'],
        aggregates=['duration:sum'],
    )
    time_by_workcenter = defaultdict(lambda: {'productive_time': 0.0, 'blocked_time': 0.0})
    for data in time_data:
        workcenter, loss_type, duration = data
        time_to_update = 'productive_time' if loss_type == 'productive' else 'blocked_time'
        time_by_workcenter[workcenter.id][time_to_update] += duration
    for workcenter in self:
        workcenter_time = time_by_workcenter[workcenter.id]
        productive_time = workcenter_time['productive_time']
        if productive_time:
            blocked_time = workcenter_time['blocked_time']
            workcenter.oee = float_round(productive_time * 100.0 / (productive_time + blocked_time), precision_digits=2)
        else:
            workcenter.oee = 0.0

def _compute_performance(self):
    wo_data = self.env['mrp.workorder']._read_group([
        ('date_start', '>=', fields.Datetime.to_string(datetime.now() - relativedelta.relativedelta(months=1))),
        ('workcenter_id', 'in', self.ids),
        ('state', '=', 'done')], ['workcenter_id'], ['duration_expected:sum', 'duration:sum'])
    duration_expected = {workcenter.id: expected for workcenter, expected, __ in wo_data}
    duration = {workcenter.id: duration for workcenter, __, duration in wo_data}
    for workcenter in self:
        if duration.get(workcenter.id):
            workcenter.performance = 100 * duration_expected.get(workcenter.id, 0.0) / duration[workcenter.id]
        else:
            workcenter.performance = 0.0

def _compute_has_routing_lines(self):
    for workcenter in self:
        workcenter.has_routing_lines = self.env['mrp.routing.workcenter'].search_count([('workcenter_id', 'in', workcenter.ids)], limit=1)

def unblock(self):
    self.ensure_one()
    if self.working_state != 'blocked':
        raise exceptions.UserError(_("It has already been unblocked."))
    times = self.env['mrp.workcenter.productivity'].search([('workcenter_id', '=', self.id), ('date_end', '=', False)])
    self.sudo().message_post(
        body=self.env._("Work Center Unblocked")
    )
    times.write({'date_end': datetime.now()})
    return True

def write(self, vals):
    if 'company_id' in vals:
        self.resource_id.company_id = vals['company_id']
    return super(MrpWorkcenter, self).write(vals)

def action_show_operations(self):
    self.ensure_one()
    action = self.env['ir.actions.actions']._for_xml_id('mrp.mrp_routing_action')
    action['domain'] = [('workcenter_id', '=', self.id)]
    action['context'] = {
        'default_workcenter_id': self.id,
    }
    return action

def action_work_order(self):
    action = self.env["ir.actions.actions"]._for_xml_id("mrp.action_work_orders")
    return action

def action_archive(self):
    res = super().action_archive()
    filtered_workcenters = ", ".join(workcenter.name for workcenter in self.filtered('routing_line_ids'))
    if filtered_workcenters:
        return {
            'type': 'ir.actions.client',
            'tag': 'display_notification',
            'params': {
            'title': _("Note that archived work center(s): '%s' is/are still linked to active Bill of Materials, which means that operations can still be planned on it/them. "
                       "To prevent this, deletion of the work center is recommended instead.", filtered_workcenters),
            'type': 'warning',
            'sticky': True,  #True/False will display for few seconds if false
            'next': {'type': 'ir.actions.act_window_close'},
            },
        }
    return res

def _get_capacity(self, product, unit, default_capacity=1):
    capacity = self.capacity_ids.sorted(lambda c: (
        not (c.product_id == product and c.uom_id == product.uom_id),
        not (not c.product_id and c.uom_id == unit),
        not (not c.product_id and c.uom_id == product.uom_id),
    ))[:1]
    if capacity and capacity.product_id in [product, self.env['product.product']] and capacity.uom_id in [product.uom_id, unit]:
        if float_is_zero(capacity.capacity, 0):
            return (default_capacity, capacity.time_start, capacity.time_stop)
        return (capacity.uom_id._compute_quantity(capacity.capacity, unit), capacity.time_start, capacity.time_stop)
    return (default_capacity, self.time_start, self.time_stop)

def _convert_to_duration(self, date_start, date_stop, workcenter=False):
    """ Convert a date range into a duration in minutes.
    If the productivity type is not from an employee (extra hours are allow)
    and the workcenter has a calendar, convert the dates into a duration based on
    working hours.
    """
    duration = 0
    for productivity_loss in self:
        if (productivity_loss.loss_type not in ('productive', 'performance')) and workcenter and workcenter.resource_calendar_id:
            r = workcenter._get_work_days_data_batch(date_start, date_stop)[workcenter.id]['hours']
            duration = max(duration, r * 60)
        else:
            duration = max(duration, (date_stop - date_start).total_seconds() / 60.0)
    return round(duration, 2)

def _compute_duration(self):
    for blocktime in self:
        if blocktime.date_start and blocktime.date_end:
            blocktime.duration = blocktime.loss_id._convert_to_duration(blocktime.date_start.replace(microsecond=0), blocktime.date_end.replace(microsecond=0), blocktime.workcenter_id)
        else:
            blocktime.duration = 0.0

def _duration_changed(self):
    if not self.date_end:
        return
    self.date_start = self.date_end - timedelta(minutes=self.duration)
    self._loss_type_change()

def _date_start_changed(self):
    if not self.date_start:
        return
    self.date_end = self.date_start + timedelta(minutes=self.duration)
    self._loss_type_change()

def _date_end_changed(self):
    if not self.date_end:
        return
    self.date_start = self.date_end - timedelta(minutes=self.duration)
    self._loss_type_change()

def _check_open_time_ids(self):
    for workorder in self.workorder_id:
        open_time_ids_by_user = self.env["mrp.workcenter.productivity"]._read_group(
            [("id", "in", workorder.time_ids.ids), ("date_end", "=", False)],
            ["user_id"], having=[("__count", ">", 1)],
        )
        if open_time_ids_by_user:
            raise ValidationError(_('The Workorder (%s) cannot be started twice!', workorder.display_name))

def button_block(self):
    self.ensure_one()
    self.workcenter_id.order_ids.end_all()
    self.workcenter_id.sudo().message_post(
        body=self.env._("Work Center Blocked: %s", self.loss_id.display_name)
    )

def _loss_type_change(self):
    self.ensure_one()
    if self.workorder_id.duration > self.workorder_id.duration_expected:
        self.loss_id = self.env.ref("mrp.block_reason4").id
    else:
        self.loss_id = self.env.ref("mrp.block_reason7").id

def _close(self):
    underperformance_timers = self.env['mrp.workcenter.productivity']
    for timer in self:
        wo = timer.workorder_id
        timer.write({'date_end': fields.Datetime.now()})
        if wo.duration > wo.duration_expected:
            productive_date_end = timer.date_end - relativedelta.relativedelta(minutes=wo.duration - wo.duration_expected)
            if productive_date_end <= timer.date_start:
                underperformance_timers |= timer
            else:
                underperformance_timers |= timer.copy({'date_start': productive_date_end})
                timer.write({'date_end': productive_date_end})
    if underperformance_timers:
        underperformance_type = self.env['mrp.workcenter.productivity.loss'].search([('loss_type', '=', 'performance')], limit=1)
        if not underperformance_type:
            raise UserError(_("You need to define at least one unactive productivity loss in the category 'Performance'. Create one from the Manufacturing app, menu: Configuration / Productivity Losses."))
        underperformance_timers.write({'loss_id': underperformance_type.id})

def _compute_uom_id(self):
    for capacity in self:
        capacity.uom_id = capacity.product_id.uom_id or self.env.ref('uom.product_uom_unit')

def get_supply_state(self, name):
    state = super().get_supply_state(name)
    if self.productions:
        states = {p.state for p in self.productions}
        if states <= {'running', 'done', 'cancelled'}:
            if states == {'cancelled'}:
                state = 'cancelled'
            else:
                state = 'supplied'
        else:
            state = 'requested'
    return state

protected String getMrpLineOriginStr(MrpLineOrigin mrpLineOrigin) {
  if (mrpLineOrigin
      .getRelatedToSelect()
      .equals(MrpLineOriginRepository.RELATED_TO_SALE_ORDER_LINE)) {
    SaleOrder saleOrder =
        saleOrderLineRepo.find(mrpLineOrigin.getRelatedToSelectId()).getSaleOrder();
    return saleOrder.getSaleOrderSeq();
  }
  if (mrpLineOrigin
      .getRelatedToSelect()
      .equals(MrpLineOriginRepository.RELATED_TO_PURCHASE_ORDER_LINE)) {
    PurchaseOrder purchaseOrder =
        purchaseOrderLineRepo.find(mrpLineOrigin.getRelatedToSelectId()).getPurchaseOrder();
    return purchaseOrder.getPurchaseOrderSeq();
  }
  if (mrpLineOrigin
      .getRelatedToSelect()
      .equals(MrpLineOriginRepository.RELATED_TO_MRP_FORECAST)) {
    return mrpLineOrigin.getMrpLine().getMrp().getMrpSeq() + "-" + I18n.get("MRP forecast");
  }
  return "";
}

public MrpLine createMrpLine(
    Mrp mrp,
    Product product,
    int maxLevel,
    MrpLineType mrpLineType,
    BigDecimal qty,
    LocalDate maturityDate,
    BigDecimal cumulativeQty,
    StockLocation stockLocation,
    Model model) {

  MrpLine mrpLine = new MrpLine();

  mrpLine.setMrp(mrp);
  mrpLine.setProduct(product);
  mrpLine.setMaxLevel(maxLevel);
  mrpLine.setMrpLineType(mrpLineType);
  if (mrpLineType.getTypeSelect() == MrpLineTypeRepository.TYPE_OUT) {
    mrpLine.setQty(qty.negate());
  } else {
    mrpLine.setQty(qty);
  }
  mrpLine.setMaturityDate(maturityDate);
  mrpLine.setCumulativeQty(cumulativeQty);
  mrpLine.setStockLocation(stockLocation);

  mrpLine = this.setMrpLineQty(mrpLine, product, stockLocation);

  if (mrpLineType.getElementSelect() == MrpLineTypeRepository.ELEMENT_PURCHASE_PROPOSAL) {
    mrpLine.setSupplierPartner(product.getDefaultSupplierPartner());
  }

  this.updatePartner(mrpLine, model);

  this.createMrpLineOrigins(mrpLine, model);

  log.debug(
      "Create mrp line for the product {}, level {}, mrpLineType {}, qty {}, maturity date {}, cumulative qty {}, stock location {}, related to {}",
      product.getCode(),
      maxLevel,
      mrpLineType.getCode(),
      qty,
      maturityDate,
      cumulativeQty,
      stockLocation.getName(),
      mrpLine.getRelatedToSelectName());

  return mrpLine;
}

protected MrpLine setMrpLineQty(MrpLine mrpLine, Product product, StockLocation stockLocation) {

  StockRules stockRules =
      stockRulesService.getStockRules(
          product,
          stockLocation,
          StockRulesRepository.TYPE_FUTURE,
          StockRulesRepository.USE_CASE_USED_FOR_MRP);

  if (stockRules != null) {
    mrpLine.setMinQty(stockRules.getMinQty());
    mrpLine.setIdealQty(stockRules.getIdealQty());
    mrpLine.setReOrderQty(stockRules.getReOrderQty());
  }
  return mrpLine;
}

protected void createMrpLineOrigins(MrpLine mrpLine, Model model) {

  if (model != null) {

    mrpLine.addMrpLineOriginListItem(this.createMrpLineOrigin(model));
    mrpLine.setRelatedToSelectName(this.computeRelatedName(model));
  }
}

public MrpLineOrigin createMrpLineOrigin(Model model) {

  Class<?> klass = EntityHelper.getEntityClass(model);

  MrpLineOrigin mrpLineOrigin = new MrpLineOrigin();
  mrpLineOrigin.setRelatedToSelect(klass.getCanonicalName());
  mrpLineOrigin.setRelatedToSelectId(model.getId());

  return mrpLineOrigin;
}

public MrpLineOrigin copyMrpLineOrigin(MrpLineOrigin mrpLineOrigin) {

  MrpLineOrigin copyMrpLineOrigin = new MrpLineOrigin();
  copyMrpLineOrigin.setRelatedToSelect(mrpLineOrigin.getRelatedToSelect());
  copyMrpLineOrigin.setRelatedToSelectId(mrpLineOrigin.getRelatedToSelectId());

  return copyMrpLineOrigin;
}

protected String computeRelatedName(Model model) {

  if (model instanceof SaleOrderLine) {

    return ((SaleOrderLine) model).getSaleOrder().getSaleOrderSeq();

  } else if (model instanceof PurchaseOrderLine) {

    return ((PurchaseOrderLine) model).getPurchaseOrder().getPurchaseOrderSeq();

  } else if (model instanceof MrpForecast) {

    MrpForecast mrpForecast = (MrpForecast) model;
    return mrpForecast.getId() + "-" + mrpForecast.getForecastDate();
  }
  return null;
}

@Override
public List<MrpLine> getMrpLineListCopy(List<MrpLine> mrpLineList) {
  List<MrpLine> copyMrpLineList = new ArrayList<>();
  mrpLineList =
      mrpLineRepo.findByIds(
          mrpLineList.stream().map(MrpLine::getId).collect(Collectors.toList()));
  for (MrpLine mrpLine : mrpLineList) {
    copyMrpLineList.add(mrpLineRepo.copy(mrpLine, true));
  }

  return copyMrpLineList;
}

def onload(self):
	self.set_onload(
		"enable_stock_reservation",
		frappe.db.get_single_value("Stock Settings", "enable_stock_reservation"),
	)

	if self.docstatus == 1:
		self.set_onload(
			"pending_work_order_qty",
			ProductionPlanWorkOrderQuantities(self.name).get_pending_quantities(self),
		)

def validate_raw_material_group_warehouse(self):
	if not self.raw_material_group_warehouse:
		return

	group = frappe.db.get_value(
		"Warehouse",
		{"name": self.raw_material_group_warehouse, "is_group": 1, "company": self.company},
		["lft", "rgt"],
		as_dict=True,
	)
	if not group:
		frappe.throw(
			_("{0} must be a group warehouse of company {1}.").format(
				frappe.bold(_("Raw Material Group Warehouse")), frappe.bold(self.company)
			)
		)

	if self.for_warehouse and not frappe.db.exists(
		"Warehouse",
		{"name": self.for_warehouse, "is_group": 0, "lft": (">", group.lft), "rgt": ("<", group.rgt)},
	):
		frappe.throw(
			_("For Warehouse {0} must be a non-group warehouse under {1}.").format(
				frappe.bold(self.for_warehouse), frappe.bold(self.raw_material_group_warehouse)
			)
		)

def enable_auto_reserve_stock(self):
	if self.is_new() and frappe.db.get_single_value("Stock Settings", "auto_reserve_stock"):
		self.reserve_stock = 1

def validate_material_request_type(self):
	for row in self.get("mr_items"):
		if row.from_warehouse and row.material_request_type != "Material Transfer":
			row.from_warehouse = ""

def validate_sales_orders(self, sales_order=None):
	sales_orders = []

	if sales_order:
		sales_orders.append(sales_order)
	else:
		sales_orders = [row.sales_order for row in self.sales_orders if row.sales_order]

	data = sales_order_query(filters={"company": self.company, "sales_orders": sales_orders})

	title = _("Production Plan Already Submitted")
	if not data and sales_orders:
		msg = _("No items are available in the sales order {0} for production").format(sales_orders[0])
		if len(sales_orders) > 1:
			sales_orders = ", ".join(sales_orders)
			msg = _("No items are available in sales orders {0} for production").format(sales_orders)

		frappe.throw(msg, title=title)

	data = [d[0] for d in data]

	for sales_order in sales_orders:
		if sales_order not in data:
			frappe.throw(
				_("No items are available in the sales order {0} for production").format(sales_order),
				title=title,
			)

def set_pending_qty_in_row_without_reference(self):
	"Set Pending Qty in independent rows (not from SO or MR)."
	if self.docstatus > 0:  # set only to initialise value before submit
		return

	for item in self.po_items:
		if not item.get("sales_order") or not item.get("material_request"):
			item.pending_qty = item.planned_qty

def calculate_total_planned_qty(self):
	self.total_planned_qty = 0
	for d in self.po_items:
		self.total_planned_qty += flt(d.planned_qty)

def validate_data(self):
	validated_boms = set()
	for d in self.get("po_items"):
		if not d.bom_no:
			frappe.throw(_("Please select BOM for Item in Row {0}").format(d.idx))
		elif (d.item_code, d.bom_no) not in validated_boms:
			validate_bom_no(d.item_code, d.bom_no)
			validated_boms.add((d.item_code, d.bom_no))

		if not flt(d.planned_qty):
			frappe.throw(
				_("Row #{0}: Planned Qty must be greater than 0 for Item {1}.").format(
					d.idx, frappe.bold(d.item_code)
				)
			)

def _rename_temporary_references(self):
	"""po_items and sub_assembly_items items are both constructed client side without saving.

	Attempt to fix linkages by using temporary names to map final row names.
	"""
	new_name_map = {d.temporary_name: d.name for d in self.po_items if d.temporary_name}
	actual_names = {d.name for d in self.po_items}

	for sub_assy in self.sub_assembly_items:
		if sub_assy.production_plan_item not in actual_names:
			sub_assy.production_plan_item = new_name_map.get(sub_assy.production_plan_item)

def get_open_sales_orders(self):
	"""Pull sales orders  which are pending to deliver based on criteria selected"""
	open_so = get_sales_orders(self)

	if open_so:
		self.add_so_in_table(open_so)
	else:
		frappe.msgprint(_("Sales orders are not available for production"))

def add_so_in_table(self, open_so):
	"""Add sales orders in the table"""
	self.set("sales_orders", [])

	for data in open_so:
		self.append(
			"sales_orders",
			{
				"sales_order": data.name,
				"sales_order_date": data.transaction_date,
				"customer": data.customer,
				"grand_total": data.base_grand_total,
			},
		)

def add_mr_in_table(self, pending_mr):
	"""Add Material Requests in the table"""
	self.set("material_requests", [])

	for data in pending_mr:
		self.append(
			"material_requests",
			{"material_request": data.name, "material_request_date": data.transaction_date},
		)

def combine_so_items(self):
	if self.combine_items and self.po_items and len(self.po_items) > 0:
		items = []
		for row in self.po_items:
			items.append(
				frappe._dict(
					{
						"parent": row.sales_order,
						"item_code": row.item_code,
						"warehouse": row.warehouse,
						"qty": row.pending_qty,
						"pending_qty": row.pending_qty,
						"conversion_factor": 1.0,
						"description": row.description,
						"bom_no": row.bom_no,
					}
				)
			)

		self.set("po_items", [])
		self.add_items(items)
	else:
		self.get_items()

def get_items(self):
	self.set("po_items", [])
	if self.get_items_from == "Sales Order":
		self.get_so_items()

	elif self.get_items_from == "Material Request":
		self.get_mr_items()

def add_items(self, items):
	refs = {}
	for data in items:
		if not data.pending_qty:
			continue

		item_details = get_item_details(data.item_code, throw=False)
		if self.combine_items:
			bom_no = item_details.get("bom_no")
			if data.get("bom_no"):
				bom_no = data.get("bom_no")

			if bom_no in refs:
				refs[bom_no]["so_details"].append(
					{"sales_order": data.parent, "sales_order_item": data.name, "qty": data.pending_qty}
				)
				refs[bom_no]["qty"] += data.pending_qty
				continue

			else:
				refs[bom_no] = {
					"qty": data.pending_qty,
					"po_item_ref": data.name,
					"so_details": [],
				}
				refs[bom_no]["so_details"].append(
					{"sales_order": data.parent, "sales_order_item": data.name, "qty": data.pending_qty}
				)

		bom_no = data.bom_no or item_details and item_details.get("bom_no") or ""
		if not bom_no:
			continue

		pi = self.append(
			"po_items",
			{
				"warehouse": data.warehouse,
				"item_code": data.item_code,
				"description": data.description or item_details.description,
				"stock_uom": item_details and item_details.stock_uom or "",
				"bom_no": bom_no,
				"planned_qty": data.pending_qty,
				"pending_qty": data.pending_qty,
				"planned_start_date": now_datetime(),
				"product_bundle_item": data.parent_item,
			},
		)
		pi._set_defaults()

		if self.get_items_from == "Sales Order":
			pi.sales_order = data.parent
			pi.sales_order_item = data.name
			pi.description = data.description

		elif self.get_items_from == "Material Request":
			pi.material_request = data.parent
			pi.material_request_item = data.name
			pi.description = data.description

	if refs:
		for po_item in self.po_items:
			po_item.planned_qty = refs[po_item.bom_no]["qty"]
			po_item.pending_qty = refs[po_item.bom_no]["qty"]
			po_item.sales_order = ""
		self.add_pp_ref(refs)

def add_pp_ref(self, refs):
	for bom_no in refs:
		for so_detail in refs[bom_no]["so_details"]:
			self.append(
				"prod_plan_references",
				{
					"item_reference": refs[bom_no]["po_item_ref"],
					"sales_order": so_detail["sales_order"],
					"sales_order_item": so_detail["sales_order_item"],
					"qty": so_detail["qty"],
				},
			)

def calculate_total_produced_qty(self):
	self.total_produced_qty = 0
	for d in self.po_items:
		self.total_produced_qty += flt(d.produced_qty)

	self.db_set("total_produced_qty", self.total_produced_qty, update_modified=False)

def update_produced_pending_qty(self, produced_qty, production_plan_item):
	for data in self.po_items:
		if data.name == production_plan_item:
			data.produced_qty = produced_qty
			data.pending_qty = flt(data.planned_qty - produced_qty)
			data.db_update()

	self.calculate_total_produced_qty()
	self.update_status_and_bin_qty()

def update_status_and_bin_qty(self):
	previous_status = self.status
	self.set_status()
	self.db_set("status", self.status)
	if previous_status != self.status and "Completed" in (previous_status, self.status):
		self.update_bin_qty()

def validate_sales_order_planned_qty(self):
	planned_qty = self.get_so_item_planned_qty()
	if not planned_qty:
		return

	already_planned = self.get_so_wise_planned_qty(list({key[0] for key in planned_qty}))
	so_items = {
		row.name: row
		for row in frappe.get_all(
			"Sales Order Item",
			filters={"name": ("in", [key[1] for key in planned_qty])},
			fields=["name", "item_code", "stock_qty", "stock_uom"],
		)
	}
	allowance = flt(
		frappe.db.get_single_value("Manufacturing Settings", "overproduction_percentage_for_sales_order")
	)
	precision = frappe.get_precision("Production Plan Item", "planned_qty")

	for (sales_order, so_item), qty in planned_qty.items():
		row = so_items[so_item]
		unplanned_qty = flt(
			flt(row.stock_qty) * (1 + allowance / 100) - flt(already_planned.get((sales_order, so_item))),
			precision,
		)
		if flt(qty, precision) > unplanned_qty:
			frappe.throw(
				_(
					"Cannot plan {0} {1} of Item {2} against Sales Order {3}. Only {4} {1} is left to plan."
				).format(
					qty, row.stock_uom, frappe.bold(row.item_code), sales_order, max(unplanned_qty, 0)
				),
				title=_("Sales Order Qty Exceeded"),
			)

def get_so_item_planned_qty(self):
	"""Planned qty per Sales Order line, excluding product bundle components."""
	planned_qty = {}
	for row in self.po_items:
		if row.sales_order and row.sales_order_item and not row.product_bundle_item:
			key = (row.sales_order, row.sales_order_item)
			planned_qty[key] = planned_qty.get(key, 0) + flt(row.planned_qty)

	return planned_qty

def update_stock_reservation(self):
	if not self.reserve_stock:
		return

	reserve_stock_for_production_plan(self)

def add_reference_to_raw_materials(self):
	for item in self.mr_items:
		if reference := next(
			(
				sa_item.name
				for sa_item in self.sub_assembly_items
				if sa_item.production_item == item.main_item_code and sa_item.bom_no == item.from_bom
			),
			None,
		):
			item.db_set("sub_assembly_item_reference", reference)
		elif (
			self.reserve_stock
			and item.main_item_code
			and item.from_bom
			and item.main_item_code != frappe.get_cached_value("BOM", item.from_bom, "item")
		):
			frappe.throw(
				_(
					"Sub assembly item references are missing. Please fetch the sub assemblies and raw materials again."
				)
			)

def update_sales_order(self):
	so_items = {
		(row.sales_order, row.sales_order_item)
		for row in self.po_items + self.prod_plan_references
		if row.sales_order and row.sales_order_item
	}
	if not so_items:
		return

	so_wise_planned_qty = self.get_so_wise_planned_qty(list({key[0] for key in so_items}))
	for key in so_items:
		frappe.db.set_value(
			"Sales Order Item", key[1], "production_plan_qty", flt(so_wise_planned_qty.get(key))
		)

def update_bin_qty(self, item_codes: set[str] | None = None):
	rows = [(d.item_code, d.warehouse) for d in self.mr_items]
	rows += [
		(d.production_item, d.fg_warehouse)
		for d in self.sub_assembly_items
		if d.type_of_manufacturing == "In House"
	]
	for item_code, warehouse in rows:
		if warehouse and (item_codes is None or item_code in item_codes):
			bin_name = get_or_make_bin(item_code, warehouse)
			bin = frappe.get_doc("Bin", bin_name, for_update=True)
			bin.update_reserved_qty_for_production_plan()

def delete_draft_work_order(self):
	for d in frappe.get_all(
		"Work Order", fields=["name"], filters={"docstatus": 0, "production_plan": ("=", self.name)}
	):
		frappe.delete_doc("Work Order", d.name)

def cancel_untouched_stock_reservations(self):
	sre_list = frappe.get_all(
		"Stock Reservation Entry",
		filters={
			"voucher_type": self.doctype,
			"voucher_no": self.name,
			"docstatus": 1,
			"status": ("in", ["Reserved", "Partially Reserved"]),
		},
		pluck="name",
	)
	for sre_name in sre_list:
		sre_doc = frappe.get_doc("Stock Reservation Entry", sre_name)
		sre_doc.flags.ignore_permissions = True
		sre_doc.cancel()

def set_status(self, close: bool | None = None, update_bin: bool = False):
	self.check_permission("write")

	if close is None and self.status == "Closed":
		return

	self.status = {0: "Draft", 1: "Submitted", 2: "Cancelled"}.get(self.docstatus)

	if close:
		self.db_set("status", "Closed")
		self.cancel_untouched_stock_reservations()
		self.update_bin_qty()
		return

	if self.total_produced_qty > 0:
		self.status = "In Process"
		if self.all_items_completed():
			self.status = "Completed"

	if self.status != "Completed":
		self.update_requested_status()
		self.update_ordered_status()

	if close is not None:
		self.db_set("status", self.status)

	if update_bin and self.docstatus == 1 and self.status != "Completed":
		self.update_bin_qty()

def update_ordered_status(self):
	for child_table in ["po_items", "sub_assembly_items"]:
		for item in self.get(child_table):
			if item.ordered_qty:
				self.status = "In Process"
				return

def update_requested_status(self):
	if self.mr_items and all(flt(d.requested_qty) >= flt(d.quantity) for d in self.mr_items):
		self.status = "Material Requested"

def validate_plan_is_open(self):
	status = (
		frappe.db.get_value("Production Plan", self.name, "status") if not self.is_new() else self.status
	)
	if status in ("Closed", "Completed"):
		frappe.throw(
			_("Production Plan {0} is {1}").format(frappe.bold(self.name), _(status)),
			frappe.InvalidStatusError,
		)

def make_work_order_for_finished_goods(self, wo_list, default_warehouses):
	items_data = self.get_production_items()

	for _key, item in items_data.items():
		if self.sub_assembly_items:
			item["use_multi_level_bom"] = 0

		set_default_warehouses(item, default_warehouses)
		work_order = self.create_work_order(item)
		if work_order:
			wo_list.append(work_order)

def make_work_order_for_subassembly_items(self, wo_list, subcontracted_po, default_warehouses):
	pending = ProductionPlanWorkOrderQuantities(self.name).get_pending_quantities(self)
	for row in self.sub_assembly_items:
		if row.type_of_manufacturing == "Subcontract":
			subcontracted_po.setdefault(row.supplier, []).append(row)
			continue

		if row.type_of_manufacturing == "Material Request":
			continue

		work_order_data = {
			"source_warehouse": frappe.get_value("BOM", row.bom_no, "default_source_warehouse"),
			"wip_warehouse": default_warehouses.get("wip_warehouse"),
			"fg_warehouse": default_warehouses.get("fg_warehouse"),
			"scrap_warehouse": default_warehouses.get("scrap_warehouse"),
			"company": self.get("company"),
		}

		self.prepare_data_for_sub_assembly_items(
			row, work_order_data, pending["production_plan_sub_assembly_item"][row.name]
		)

		if work_order_data.get("qty") <= 0:
			continue

		work_order = self.create_work_order(work_order_data)
		if work_order:
			wo_list.append(work_order)

def get_subcontracted_qty(self):
	po_item = frappe.qb.DocType("Purchase Order Item")
	return frappe._dict(
		(
			frappe.qb.from_(po_item)
			.select(po_item.production_plan_sub_assembly_item, Sum(po_item.fg_item_qty))
			.where((po_item.production_plan == self.name) & (po_item.docstatus < 2))
			.groupby(po_item.production_plan_sub_assembly_item)
		).run()
	)

def show_list_created_message(self, doctype, doc_list=None):
	if not doc_list:
		return

	frappe.flags.mute_messages = False
	msgprint(_("{0} created").format(get_filtered_list_link(doctype, doc_list)))

def validate_mr_subcontracted(self):
	for row in self.mr_items:
		if row.material_request_type == "Subcontracting":
			if not frappe.db.get_value("Item", row.item_code, "is_sub_contracted_item"):
				frappe.throw(
					_("Item {0} is not a subcontracted item").format(row.item_code),
					title=_("Invalid Item"),
				)

def make_material_request(self):
	self.load_saved_plan_for_material_request()
	self.validate_mr_subcontracted()

	"""Create Material Requests grouped by Sales Order and Material Request Type"""
	material_request_list = []
	material_request_map = {}
	draft_qty = self.get_draft_requested_qty()

	for item in self.mr_items:
		qty_to_request = get_qty_to_request(item, draft_qty)
		if qty_to_request <= 0:
			continue

		item_doc = frappe.get_cached_doc("Item", item.item_code)

		# a group warehouse cannot receive stock; it must never reach a Material Request line
		if item.warehouse and frappe.get_cached_value("Warehouse", item.warehouse, "is_group"):
			frappe.throw(
				_("Cannot create Material Request for item {0} in group warehouse {1}.").format(
					frappe.bold(item.item_code), frappe.bold(item.warehouse)
				)
			)

		material_request_type = item.material_request_type or item_doc.default_material_request_type

		# key for Sales Order:Material Request Type:Customer
		key = "{}:{}:{}".format(item.sales_order, material_request_type, "")
		schedule_date = item.schedule_date or add_days(nowdate(), cint(item_doc.lead_time_days))

		if key not in material_request_map:
			# make a new MR for the combination
			material_request_map[key] = frappe.new_doc("Material Request")
			material_request = material_request_map[key]
			material_request.update(
				{
					"transaction_date": nowdate(),
					"status": "Draft",
					"company": self.company,
					"material_request_type": material_request_type,
				}
			)
			material_request_list.append(material_request)
		else:
			material_request = material_request_map[key]

		# add item
		material_request.append(
			"items",
			{
				"item_code": item.item_code,
				"from_warehouse": item.from_warehouse
				if material_request_type == "Material Transfer"
				else None,
				"qty": qty_to_request,
				"uom": item.uom,
				"schedule_date": schedule_date,
				"warehouse": item.warehouse,
				"sales_order": item.sales_order,
				"production_plan": self.name,
				"material_request_plan_item": item.name,
				"project": frappe.db.get_value("Sales Order", item.sales_order, "project")
				if item.sales_order
				else None,
			},
		)

	if not material_request_list:
		msgprint(_("All items are already requested"))
		return

	for material_request in material_request_list:
		# submit
		material_request.flags.ignore_permissions = 1
		material_request.run_method("set_missing_values")

		material_request.save()
		if self.get("submit_material_request"):
			material_request.submit()

	frappe.flags.mute_messages = False

	if material_request_list:
		material_request_list = [
			get_link_to_form("Material Request", m.name) for m in material_request_list
		]
		msgprint(_("{0} created").format(comma_and(material_request_list)))
	else:
		msgprint(_("No material request created"))

def get_draft_requested_qty(self):
	mr_item = frappe.qb.DocType("Material Request Item")
	return frappe._dict(
		(
			frappe.qb.from_(mr_item)
			.select(mr_item.material_request_plan_item, Sum(mr_item.stock_qty))
			.where((mr_item.production_plan == self.name) & (mr_item.docstatus == 0))
			.groupby(mr_item.material_request_plan_item)
		).run()
	)

def set_sub_assembly_items_based_on_level(self, row, bom_data, manufacturing_type=None):
	"Modify bom_data, set additional details."
	is_group_warehouse = frappe.db.get_value("Warehouse", self.sub_assembly_warehouse, "is_group")

	for data in bom_data:
		data.qty = data.stock_qty
		data.production_plan_item = row.name
		data.schedule_date = row.planned_start_date
		data.type_of_manufacturing = manufacturing_type or (
			"Subcontract" if data.is_sub_contracted_item else "In House"
		)

		if not is_group_warehouse:
			data.fg_warehouse = self.sub_assembly_warehouse

		if not self.combine_sub_items:
			data.sales_order = row.sales_order
			data.sales_order_item = row.sales_order_item

def all_items_completed(self):
	all_items_produced = all(flt(d.planned_qty) - flt(d.produced_qty) < 0.000001 for d in self.po_items)
	if not all_items_produced:
		return False

	wo_status = frappe.get_all(
		"Work Order",
		filters={
			"production_plan": self.name,
			"status": ("not in", ["Closed", "Stopped"]),
			"docstatus": 1,
		},
		fields="status",
		pluck="status",
	)
	all_work_orders_completed = all(s == "Completed" for s in wo_status)
	return all_work_orders_completed

def get_mr_item_planned_qty_query(mr_item):
	plan_item = frappe.qb.DocType("Production Plan Item")
	return (
		frappe.qb.from_(plan_item)
		.select(Sum(plan_item.planned_qty))
		.where((plan_item.material_request_item == mr_item.name) & (plan_item.docstatus == 1))
	)

def get_planned_qty_by_order_row(plans):
	plan_item = frappe.qb.DocType("Production Plan Item")
	rows = (
		frappe.qb.from_(plan_item)
		.select(plan_item.parent, plan_item.sales_order_item, Sum(plan_item.planned_qty).as_("qty"))
		.where(plan_item.parent.isin(plans))
		.groupby(plan_item.parent, plan_item.sales_order_item)
	).run(as_dict=True)
	return {(row.parent, row.sales_order_item): flt(row.qty) for row in rows}

def get_qty_to_request(item, draft_qty):
	qty_to_request = flt(
		flt(item.quantity)
		- flt(item.requested_qty)
		- flt(draft_qty.get(item.name)) / (flt(item.conversion_factor) or 1),
		item.precision("quantity"),
	)
	if qty_to_request > 0 and frappe.get_cached_value("UOM", item.uom, "must_be_whole_number"):
		qty_to_request = ceil(qty_to_request)

	return qty_to_request

def get_requested_sub_assemblies(doc):
	requested_sub_assemblies = {}
	for row in doc.get("sub_assembly_items") or []:
		row = frappe._dict(row)
		if row.type_of_manufacturing == "Material Request":
			requested_sub_assemblies.setdefault(row.production_plan_item, set()).add(
				(row.production_item, row.bom_no)
			)

	return requested_sub_assemblies

def _authorize_mr_request(doc, warehouses=None):
	"""Scope a caller-supplied plan to what the caller may see; `doc` is often unsaved, so check only a real name.

	`warehouses` is accepted so the call site reads the same as on develop, where it also narrows
	the caller to their permitted companies. There is no Company Restriction on this branch.
	"""
	name = doc.get("name")
	if isinstance(name, str) and frappe.db.exists("Production Plan", name):
		frappe.has_permission("Production Plan", doc=name, throw=True)

	# Values arrive through frappe.parse_json, so container elements are untyped: a dict reaches
	# frappe.db.get_value() in its *name* position and becomes a filter.
	for row in _iter_mr_rows(doc):
		for fieldname in ("item_code", "warehouse", "bom_no", "sales_order", "uom", "purchase_uom"):
			value = row.get(fieldname)
			if value is not None and not isinstance(value, str):
				frappe.throw(_("Invalid {0}").format(fieldname), frappe.PermissionError)

def get_reserved_qty_for_production_plan(item_code, warehouse):
	plan_reservations = _get_plan_reservations(item_code)
	if not plan_reservations:
		return None

	work_order_reservations = _get_work_order_reservations(item_code, list(plan_reservations))
	reserved_qty = 0.0
	for plan, plan_qty_by_warehouse in plan_reservations.items():
		reserved_qty += _get_remaining_reserved_qty(
			plan_qty_by_warehouse, work_order_reservations.get(plan, {}), warehouse
		)

	return reserved_qty

def _get_plan_reservations(item_code):
	return _group_by_plan_and_warehouse(
		_get_material_request_plan_query(item_code), _get_sub_assembly_plan_query(item_code)
	)

def _group_by_plan_and_warehouse(*queries):
	reservations = defaultdict(lambda: defaultdict(float))
	for query in queries:
		for row in query.run(as_dict=True):
			reservations[row.production_plan][row.warehouse] += flt(row.reserved_qty)
	return reservations

def get_non_completed_production_plans():
	table = frappe.qb.DocType("Production Plan")

	return (
		frappe.qb.from_(table)
		.select(table.name)
		.distinct()
		.where((table.docstatus == 1) & (table.status.notin(["Completed", "Closed"])))
	).run(pluck="name")

def reserve_stock_for_production_plan(doc, items=None, table_name=None, notify=False):
	"""Reserve stock for a Production Plan. Internal: no permission check, because the Production
	Plan submit and cancel lifecycles reach it for a user who need not hold Production Plan write.
	The cancelled branch unreserves, so the whitelisted entry point above needs the same right as
	the cancel sibling.
	"""
	if items and isinstance(items, str):
		items = parse_json(items)

	mapper = {
		"sub_assembly_items": {
			"table_name": "sub_assembly_items",
			"qty_field": "required_qty",
			"warehouse_field": "fg_warehouse",
		},
		"mr_items": {
			"table_name": "mr_items",
			"qty_field": "required_bom_qty",
			"warehouse_field": "warehouse",
		},
	}

	for child_table_name in mapper:
		if table_name and table_name != child_table_name:
			continue

		sre = StockReservation(doc, items=items, kwargs=mapper[child_table_name], notify=notify)
		if doc.docstatus == 1:
			sre_created = sre.make_stock_reservation_entries()
			if sre_created:
				frappe.msgprint(_("Stock Reservation Entries Created"), alert=True)
		elif doc.docstatus == 2:
			sre.cancel_stock_reservation_entries()

	doc.reload()

def validate_with_previous_doc(self):
	super().validate_with_previous_doc(
		{
			"Sales Order": {
				"ref_dn_field": "sales_order",
				"compare_fields": [["company", "="]],
			},
			"Sales Order Item": {
				"ref_dn_field": "sales_order_item",
				"compare_fields": [["item_code", "="], ["uom", "="], ["conversion_factor", "="]],
				"is_child_table": True,
				"allow_duplicate_prev_row_id": True,
			},
		}
	)

def validate_qty_against_so(self):
	so_items = {}  # Format --> {'SO/00001': {'Item/001': 120, 'Item/002': 24}}
	for d in self.get("items"):
		if d.sales_order:
			if d.sales_order not in so_items:
				so_items[d.sales_order] = {d.item_code: flt(d.qty)}
			else:
				if d.item_code not in so_items[d.sales_order]:
					so_items[d.sales_order][d.item_code] = flt(d.qty)
				else:
					so_items[d.sales_order][d.item_code] += flt(d.qty)

	for so_no in so_items.keys():
		for item in so_items[so_no].keys():
			already_indented = frappe.db.sql(
				"""select sum(qty)
				from `tabMaterial Request Item`
				where item_code = %s and sales_order = %s and
				docstatus = 1 and parent != %s""",
				(item, so_no, self.name),
			)
			already_indented = already_indented and flt(already_indented[0][0]) or 0

			actual_so_qty = frappe.db.sql(
				"""select sum(stock_qty) from `tabSales Order Item`
				where parent = %s and item_code = %s and docstatus = 1""",
				(so_no, item),
			)
			actual_so_qty = actual_so_qty and flt(actual_so_qty[0][0]) or 0

			if actual_so_qty and (flt(so_items[so_no][item]) + already_indented > actual_so_qty):
				frappe.throw(
					_(
						"Material Request of maximum {0} can be made for Item {1} against Sales Order {2}"
					).format(actual_so_qty - already_indented, item, so_no)
				)

def set_buying_price_list(self):
	if not is_valid_buying_price_list(self.buying_price_list):
		self.buying_price_list = None

	if self.buying_price_list:
		return

	default_price_list = frappe.defaults.get_defaults().buying_price_list
	if is_valid_buying_price_list(default_price_list) and frappe.has_permission(
		"Price List", "read", default_price_list
	):
		self.buying_price_list = default_price_list

def on_update(self):
	if not self.is_new() and self.buying_price_list and self.has_value_changed("buying_price_list"):
		self.update_item_rates()

def update_item_rates(self):
	price_not_uom_dependent = frappe.get_value(
		"Price List", self.buying_price_list, "price_not_uom_dependent"
	)
	for item in self.items:
		rate = get_price_list_rate_for(
			frappe._dict(
				{
					"price_list": self.buying_price_list,
					"uom": item.uom,
					"transaction_date": self.transaction_date,
					"qty": item.qty,
					"stock_uom": item.stock_uom,
					"conversion_factor": item.conversion_factor,
					"price_list_uom_dependant": price_not_uom_dependent,
				}
			),
			item.item_code,
		)
		if rate is not None:
			item.db_set({"rate": rate, "amount": flt(rate * item.qty, item.precision("amount"))})

	frappe.msgprint(
		_("Item rates have been updated based on the selected Buying Price List {0}").format(
			self.buying_price_list
		),
		alert=True,
	)

def validate_pp_qty(self):
	items_from_pp = [item for item in self.items if item.material_request_plan_item]
	if not items_from_pp:
		return

	plan_items = self.get_plan_items(items_from_pp)
	requested_qty = {}
	for item in items_from_pp:
		row = plan_items[item.material_request_plan_item]
		precision = item.precision("qty")
		available_qty = flt(flt(row.quantity) - flt(row.requested_qty), precision)
		qty = get_qty_in_plan_uom(item, row)
		requested_qty[row.name] = requested_qty.get(row.name, 0) + qty
		if max(flt(qty, precision), flt(requested_qty[row.name], precision)) > available_qty:
			frappe.throw(
				_("Quantity cannot be greater than {0} for Item {1}").format(
					available_qty, item.item_code
				)
			)

def get_plan_items(self, items):
	return {
		row.name: row
		for row in frappe.get_all(
			"Material Request Plan Item",
			filters={"name": ("in", {item.material_request_plan_item for item in items})},
			fields=["name", "quantity", "requested_qty", "conversion_factor"],
		)
	}

def validate_material_request_type(self):
	"""Validate fields in accordance with selected type"""

	if self.material_request_type == "Customer Provided":
		self.validate_customer_provided_items()
	else:
		self.customer = None

	if self.material_request_type == "Subcontracting":
		self.validate_subcontracted_items()

def validate_customer_provided_items(self):
	items = {d.item_code for d in self.items if d.item_code}
	provided_items = frappe.get_all(
		"Item", filters={"name": ("in", items), "is_customer_provided_item": 1}, pluck="name"
	)
	if other_items := items - set(provided_items):
		frappe.throw(
			_("Items {0} are not Customer Provided Items").format(
				", ".join(frappe.bold(d) for d in sorted(other_items))
			)
		)

def validate_subcontracted_items(self):
	items = frappe.get_all(
		"Item",
		filters={"name": ["in", list({d.item_code for d in self.items if d.item_code})]},
		fields=["name", "is_stock_item", "is_sub_contracted_item"],
	)
	items = {d.name: d for d in items}

	for row in self.items:
		item = items.get(row.item_code)
		if item and not (item.is_stock_item and item.is_sub_contracted_item):
			frappe.throw(
				_(
					"Row #{0}: Item {1} must be a stock item with Supply Raw Materials for Purchase enabled for a Subcontracting Material Request"
				).format(row.idx, get_link_to_form("Item", row.item_code)),
				title=_("Invalid Item"),
			)

def set_title(self):
	"""Set title as comma separated list of items"""
	if not self.title:
		items = ", ".join([d.item_name for d in self.items][:3])
		self.title = _("{0} Request for {1}").format(_(self.material_request_type), items)[:100]

def on_submit(self):
	self.update_requested_qty_in_production_plan()
	self.update_requested_qty()
	self.update_requested_qty_in_job_card()
	self.update_prevdoc_status()
	if self.material_request_type == "Purchase" and frappe.db.exists(
		"Budget", {"applicable_on_material_request": 1, "docstatus": 1}
	):
