def check_modified_date(self):
	mod_db = frappe.db.sql("""select modified from `tabMaterial Request` where name = %s""", self.name)
	date_diff = frappe.db.sql("""select TIMEDIFF(%s, %s)""", (mod_db[0][0], cstr(self.modified)))

	if date_diff and date_diff[0][0]:
		frappe.throw(_("{0} {1} has been modified. Please refresh.").format(_(self.doctype), self.name))

def status_can_change(self, status):
	"""
	validates that `status` is acceptable for the present controller status
	and throws an Exception if otherwise.
	"""
	if self.status and self.status == "Cancelled":
		# cancelled documents cannot change
		if status != self.status:
			frappe.throw(
				_("{0} {1} is cancelled so the action cannot be completed").format(
					_(self.doctype), self.name
				),
				frappe.InvalidStatusError,
			)

	elif self.status and self.status == "Draft":
		# draft document to pending only
		if status != "Pending":
			frappe.throw(
				_("{0} {1} has not been submitted so the action cannot be completed").format(
					_(self.doctype), self.name
				),
				frappe.InvalidStatusError,
			)

def get_mr_items_ordered_qty(self, mr_items):
	mr_items_ordered_qty = {}
	mr_items = [d.name for d in self.get("items") if d.name in mr_items]

	doctype = qty_field = None
	if self.material_request_type in ("Material Issue", "Material Transfer", "Customer Provided"):
		doctype = frappe.qb.DocType("Stock Entry Detail")
		qty_field = doctype.transfer_qty
	elif self.material_request_type == "Manufacture":
		doctype = frappe.qb.DocType("Work Order")
		qty_field = (
			Case()
			.when(
				(doctype.status == "Closed") & (doctype.produced_qty < doctype.qty), doctype.produced_qty
			)
			.else_(doctype.qty)
		)

	if doctype and qty_field:
		query = (
			frappe.qb.from_(doctype)
			.select(doctype.material_request_item, Sum(qty_field))
			.where(
				(doctype.material_request == self.name)
				& (doctype.material_request_item.isin(mr_items))
				& (doctype.docstatus == 1)
			)
			.groupby(doctype.material_request_item)
		)

		mr_items_ordered_qty = frappe._dict(query.run())

	return mr_items_ordered_qty

def update_completed_qty(self, mr_items=None, update_modified=True):
	if self.material_request_type == "Purchase":
		return

	if not mr_items:
		mr_items = [d.name for d in self.get("items")]

	mr_items_ordered_qty = self.get_mr_items_ordered_qty(mr_items)
	mr_qty_allowance = frappe.db.get_single_value("Stock Settings", "mr_qty_allowance")

	for d in self.get("items"):
		precision = d.precision("ordered_qty")
		if d.name in mr_items:
			if self.material_request_type in ("Material Issue", "Material Transfer", "Customer Provided"):
				d.ordered_qty = flt(mr_items_ordered_qty.get(d.name))

				if mr_qty_allowance:
					allowed_qty = flt(
						(d.stock_qty + (d.stock_qty * (mr_qty_allowance / 100))),
						d.precision("ordered_qty"),
					)

					if d.ordered_qty and flt(d.ordered_qty, precision) > flt(allowed_qty, precision):
						frappe.throw(
							_(
								"The total Issue / Transfer quantity {0} in Material Request {1}  cannot be greater than allowed requested quantity {2} for Item {3}"
							).format(d.ordered_qty, d.parent, allowed_qty, d.item_code)
						)

				elif d.ordered_qty and flt(d.ordered_qty, precision) > flt(d.stock_qty, precision):
					frappe.throw(
						_(
							"The total Issue / Transfer quantity {0} in Material Request {1} cannot be greater than requested quantity {2} for Item {3}"
						).format(d.ordered_qty, d.parent, d.qty, d.item_code)
					)

			elif self.material_request_type == "Manufacture":
				ordered_qty = flt(mr_items_ordered_qty.get(d.name))
				self.validate_work_order_qty(d, ordered_qty, mr_qty_allowance)
				d.ordered_qty = ordered_qty

			frappe.db.set_value(d.doctype, d.name, "ordered_qty", d.ordered_qty)

	self._update_percent_field(
		{
			"target_dt": "Material Request Item",
			"target_parent_dt": self.doctype,
			"target_parent_field": "per_ordered",
			"target_ref_field": "stock_qty",
			"target_field": "ordered_qty",
			"name": self.name,
		},
		update_modified,
	)

def update_requested_qty_in_job_card(self):
	if self.job_card:
		frappe.get_doc("Job Card", self.job_card).set_requested_qty()

def validate_work_order_qty(self, row, ordered_qty, mr_qty_allowance):
	precision = row.precision("ordered_qty")
	if flt(ordered_qty, precision) <= flt(row.ordered_qty, precision):
		return

	if self.status == "Stopped":
		frappe.throw(_("Material Request {0} is stopped").format(self.name), frappe.InvalidStatusError)

	allowed_qty = flt(row.stock_qty + row.stock_qty * flt(mr_qty_allowance) / 100, precision)
	if flt(ordered_qty, precision) > allowed_qty:
		frappe.throw(
			_(
				"The total Work Order quantity {0} in Material Request {1} cannot be greater than allowed requested quantity {2} for Item {3}"
			).format(ordered_qty, self.name, allowed_qty, row.item_code)
		)

def update_requested_qty(self, mr_item_rows=None):
	"""update requested qty (before ordered_qty is updated)"""
	item_warehouses = dict.fromkeys(
		(d.item_code, d.warehouse)
		for d in self.get("items")
		if d.warehouse and (not mr_item_rows or d.name in mr_item_rows)
	)
	if not item_warehouses:
		return

	stock_items = set(
		frappe.get_all(
			"Item",
			filters={
				"name": ("in", {item_code for item_code, warehouse in item_warehouses}),
				"is_stock_item": 1,
			},
			pluck="name",
		)
	)

	for item_code, warehouse in item_warehouses:
		if item_code not in stock_items:
			continue

		update_bin_qty(
			item_code,
			warehouse,
			{
				"indented_qty": get_indented_qty(item_code, warehouse),
			},
		)

def update_requested_qty_in_production_plan(self, cancel=False):
	items_from_pp = [d for d in self.items if d.production_plan and d.material_request_plan_item]
	if not items_from_pp:
		return

	update_plan_item_requested_qty({d.material_request_plan_item for d in items_from_pp})

	for production_plan in {d.production_plan for d in items_from_pp}:
		doc = frappe.get_doc("Production Plan", production_plan)
		doc.flags.ignore_permissions = True
		doc.set_status()
		doc.db_set("status", doc.status)

def validate_request_not_stopped(source_name):
	if frappe.db.get_value("Material Request", source_name, "status") == "Stopped":
		frappe.throw(_("Material Request {0} is stopped").format(source_name), frappe.InvalidStatusError)

def update_completed_and_requested_qty(stock_entry, method):
	if stock_entry.doctype == "Stock Entry":
		material_request_map = {}

		for d in stock_entry.get("items"):
			if d.material_request:
				material_request_map.setdefault(d.material_request, []).append(d.material_request_item)

		for mr, mr_item_rows in material_request_map.items():
			if mr and mr_item_rows:
				mr_obj = frappe.get_doc("Material Request", mr)

				if mr_obj.status in ["Stopped", "Cancelled"]:
					frappe.throw(
						_("{0} {1} is cancelled or stopped").format(_("Material Request"), mr),
						frappe.InvalidStatusError,
					)

				mr_obj.update_completed_qty(mr_item_rows)
				mr_obj.update_requested_qty(mr_item_rows)

def make_request_for_quotation(source_name: str, target_doc: str | dict | Document | None = None):
	validate_request_not_stopped(source_name)

	def update_item(obj, target, source_parent):
		qty = obj.ordered_qty or obj.received_qty
		target.qty = flt(flt(obj.stock_qty) - flt(qty)) / target.conversion_factor
		target.stock_qty = target.qty * target.conversion_factor

	def select_item(d):
		qty = d.ordered_qty or d.received_qty
		return qty < d.stock_qty

	doclist = get_mapped_doc(
		"Material Request",
		source_name,
		{
			"Material Request": {
				"doctype": "Request for Quotation",
				"validation": {"docstatus": ["=", 1], "material_request_type": ["=", "Purchase"]},
			},
			"Material Request Item": {
				"doctype": "Request for Quotation Item",
				"field_map": [
					["name", "material_request_item"],
					["parent", "material_request"],
					["project", "project_name"],
				],
				"postprocess": update_item,
				"condition": select_item,
			},
		},
		target_doc,
	)

	return doclist

