              mrpForecast.getUnit(), unit, qty, qty.scale(), mrpForecast.getProduct());
    }
    MrpLine mrpLine =
        this.createMrpLine(
            mrp,
            mrpForecast.getProduct(),
            saleForecastMrpLineType,
