protected LocalDate computeMaturityDate(LocalDate maturityDate, MrpLineType mrpLineType) {
  if ((maturityDate != null && maturityDate.isBefore(today))
      || (maturityDate == null && mrpLineType.getIncludeElementWithoutDate())) {
    maturityDate = today;
  }
  return maturityDate;
}

