public boolean isMrpProduct(Product product) {
  return product != null
      && Boolean.FALSE.equals(product.getExcludeFromMrp())
      && ProductRepository.PRODUCT_TYPE_STORABLE.equals(product.getProductTypeSelect());
}

protected MrpLine createMrpLine(
    Mrp mrp,
    Product product,
    MrpLineType mrpLineType,
    BigDecimal qty,
    LocalDate maturityDate,
    BigDecimal cumulativeQty,
    StockLocation stockLocation,
    Model model)
    throws AxelorException {

  if (productMap != null && product != null) {
    if (product.getUnit() == null) {
      throw new AxelorException(
          TraceBackRepository.CATEGORY_CONFIGURATION_ERROR,
          I18n.get(SupplychainExceptionMessage.MRP_NO_PRODUCT_UNIT),
          product.getFullName());
    }
    Long productId = product.getId();
    if (!this.productMap.containsKey(productId)) {
      if (currentLevel == null) {
        currentLevel = 0;
      }
      int nextLevel = currentLevel + 1;
      if (this.productMapToBeAssigned == null) {
        this.productMapToBeAssigned = new HashMap<>();
      }
      this.productMap.put(productId, nextLevel);
      this.productMapToBeAssigned.put(productId, nextLevel);
    }
    return mrpLineService.createMrpLine(
        mrp,
        product,
        this.productMap.get(productId),
        mrpLineType,
        qty,
        maturityDate,
        cumulativeQty,
        mrp.getComputeWithSubStockLocation() ? stockLocation : mrp.getStockLocation(),
        model);
  }
  return null;
}

