@Override
public LocalDate findMrpEndDate(Mrp mrp) {
  if (mrp.getEndDate() != null) {
    return mrp.getEndDate();
  }

  MrpLine mrpLine =
      mrpLineRepository
          .all()
          .filter("self.mrp.id = ?1", mrp.getId())
          .order("-maturityDate")
          .fetchOne();

  if (mrpLine != null && mrpLine.getMaturityDate() != null) {
    return mrpLine.getMaturityDate();
  }

  return today;
}

